import { readFile } from "node:fs/promises";
import { createBucket, list, get, put } from "@tigrisdata/storage";

async function main() {
  // 1. Read the current trial_id
  const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
  const trialId = trialIdRaw.trim();
  console.log(`Trial ID: ${trialId}`);

  // 2. Compute the bucket names
  const srcBucket = `harbor-src-${trialId}`;
  const dstBucket = `harbor-dst-${trialId}`;
  console.log(`Source Bucket: ${srcBucket}`);
  console.log(`Destination Bucket: ${dstBucket}`);

  // 3. Create the destination bucket
  console.log(`Creating destination bucket: ${dstBucket}`);
  const { error: createError } = await createBucket(dstBucket);
  if (createError) {
    console.log("Error creating bucket (ignoring and proceeding):", createError.message);
  } else {
    console.log("Destination bucket created successfully.");
  }

  // 4. List objects in the source bucket
  console.log(`Listing objects in source bucket: ${srcBucket} with prefix 'data/'`);
  const { data: objects, error: listError } = await list({
    prefix: "data/",
    config: { bucket: srcBucket },
  });

  if (listError) {
    console.error("Error listing objects:", listError);
    // FALLBACK: Try with lowercase and hyphens if original fails
    const srcBucketAlt = `harbor-src-${trialId}`.toLowerCase().replace(/_/g, "-");
    const dstBucketAlt = `harbor-dst-${trialId}`.toLowerCase().replace(/_/g, "-");
    console.log(`Retrying with alternative bucket names: ${srcBucketAlt} -> ${dstBucketAlt}`);

    // Try to create alternative destination
    await createBucket(dstBucketAlt);

    const { data: objectsAlt, error: listErrorAlt } = await list({
        prefix: "data/",
        config: { bucket: srcBucketAlt },
    });

    if (listErrorAlt) {
        console.error("Alternative list also failed:", listErrorAlt);
        process.exit(1);
    }

    if (objectsAlt) {
        await processObjects(objectsAlt, srcBucketAlt, dstBucketAlt);
    }
  } else if (objects) {
    await processObjects(objects, srcBucket, dstBucket);
  }

  console.log("Copy operation completed successfully.");
}

async function processObjects(objects: any[], src: string, dst: string) {
    console.log(`Found ${objects.length} objects.`);
    for (const obj of objects) {
        const name = obj.name;
        console.log(`Copying ${name} from ${src} to ${dst}...`);
        const { data: body, error: getError } = await get(name, "string", {
            config: { bucket: src },
        });
        if (getError) {
            console.error(`Error getting object ${name}:`, getError);
            process.exit(1);
        }
        const { error: putError } = await put(name, body, {
            config: { bucket: dst },
        });
        if (putError) {
            console.error(`Error putting object ${name}:`, putError);
            process.exit(1);
        }
        console.log(`Successfully copied ${name}`);
    }
}

main().catch((err) => {
  console.error("Unhandled error:", err);
  process.exit(1);
});
